import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.9yf7n3zg.js";const n="/guide/media/languages-app-language.webp",r="/guide/media/languages-story-language.webp",m=JSON.parse('{"title":"Languages","description":"","frontmatter":{},"headers":[],"relativePath":"reference/languages.md","filePath":"reference/languages.md","lastUpdated":1792112190000}'),i={name:"reference/languages.md"};function d(h,e,l,g,u,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="languages" tabindex="-1">Languages <a class="header-anchor" href="#languages" aria-label="Permalink to &quot;Languages&quot;">​</a></h1><p>Leathercase keeps three languages apart: the language the app speaks to you, the language each story is written in, and the language of the book an export writes. They differ more often than you might think. A Brazilian novelist may run the app in Portuguese while drafting a novel in English, and a Lisbon screenwriter may keep the app in English while writing in Portuguese. Tying the three together would get one of them wrong for that writer, so each has its own setting.</p><h2 id="the-three-languages" tabindex="-1">The three languages <a class="header-anchor" href="#the-three-languages" aria-label="Permalink to &quot;The three languages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Language</th><th>What it decides</th><th>Where you set it</th><th>Kept</th></tr></thead><tbody><tr><td><strong>The app&#39;s</strong></td><td>Menus, labels, buttons, the Desk&#39;s sentences, dates and numbers in the interface</td><td><strong>Settings</strong>, <strong>Appearance</strong>, <strong>Language of the app</strong></td><td>On this computer only</td></tr><tr><td><strong>The story&#39;s</strong></td><td>How the prose is read (names, honorifics, pronouns, which little words are not names) and the words Leathercase writes for the story: beats, template acts and scenes, columns</td><td><strong>Story settings</strong>, <strong>Language</strong></td><td>In the story&#39;s <code>Story.json</code>, so it travels with the story</td></tr><tr><td><strong>The book&#39;s</strong></td><td>The words an export writes into the manuscript: &quot;Contents&quot;, &quot;Chapter One&quot;, &quot;by&quot;, &quot;END&quot;, the scene break, &quot;about 1,000 words&quot;, the file&#39;s name</td><td>Follows the story&#39;s language</td><td></td></tr></tbody></table><p>The app&#39;s language never reaches your files or your book. A Portuguese story exported from an English desk reads &quot;Capítulo Um&quot; and &quot;cerca de 1.000 palavras&quot;, with no &quot;Chapter&quot; or &quot;about&quot; in it.</p><h2 id="reading-is-not-translating" tabindex="-1">Reading is not translating <a class="header-anchor" href="#reading-is-not-translating" aria-label="Permalink to &quot;Reading is not translating&quot;">​</a></h2><p>Leathercase reads more languages in your files than the app is translated into. Reading means it finds names, pronouns, titles and folder names in your prose and your folders, whatever language the app speaks to you. Translating means the app&#39;s own menus and labels are in that language.</p><table tabindex="0"><thead><tr><th></th><th>Languages</th></tr></thead><tbody><tr><td>Recognised in your files</td><td>English, Portuguese, Spanish, French, German, Italian</td></tr><tr><td>The app is translated into</td><td>English (United States, United Kingdom, Canada), Portuguese (Brazil, Portugal)</td></tr></tbody></table><p>A Spanish novel opened in the app&#39;s English is read as Spanish: its <code>Personajes/</code> folder is the cast, and &quot;ella&quot; finds the woman just named. The app&#39;s labels stay in English.</p><h2 id="the-app-s-language" tabindex="-1">The app&#39;s language <a class="header-anchor" href="#the-app-s-language" aria-label="Permalink to &quot;The app&#39;s language&quot;">​</a></h2><p>The app speaks the language of the computer it runs on, matched to the nearest language it carries, until you pick another.</p><p><img src="'+n+'" alt="Settings at Appearance, with the Language group at the top and the Language of the app list set to Follow the system, naming the language it found" width="845" height="319" loading="lazy"></p><ol><li>Open <strong>Settings</strong> (<code>Ctrl+,</code>, or <code>Cmd+,</code> on macOS).</li><li>Choose <strong>Appearance</strong>.</li><li>Under <strong>Language</strong>, pick from <strong>Language of the app</strong>: <strong>Follow the system</strong> (the line names the language it found), or one of the languages below.</li></ol><p>The change applies at once, to the window and to the native menus (File, Edit, Story, View). It is this computer&#39;s choice: another computer that syncs the same writing home keeps its own. In the menus, the few items the system words itself, such as Quit, Cut and Paste, follow the system&#39;s.</p><h3 id="languages-the-app-carries" tabindex="-1">Languages the app carries <a class="header-anchor" href="#languages-the-app-carries" aria-label="Permalink to &quot;Languages the app carries&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Language</th><th>Shown as</th><th>How it is made</th></tr></thead><tbody><tr><td><code>en-US</code></td><td>English (United States)</td><td>The source: every string is written here first</td></tr><tr><td><code>en-GB</code></td><td>English (United Kingdom)</td><td>British spelling and quotes; only what differs from en-US</td></tr><tr><td><code>en-CA</code></td><td>English (Canada)</td><td>Canadian spelling; only what differs from en-US</td></tr><tr><td><code>pt-BR</code></td><td>Português (Brasil)</td><td>A full translation</td></tr><tr><td><code>pt-PT</code></td><td>Português (Portugal)</td><td>European Portuguese vocabulary and grammar; only what differs from pt-BR</td></tr></tbody></table><p>A message an overlay does not change comes from the language it is built on: en-GB and en-CA from en-US, pt-PT from pt-BR and then en-US.</p><h3 id="how-follow-the-system-chooses" tabindex="-1">How &quot;Follow the system&quot; chooses <a class="header-anchor" href="#how-follow-the-system-chooses" aria-label="Permalink to &quot;How &quot;Follow the system&quot; chooses&quot;">​</a></h3><p>Leathercase reads the languages your system lists, in their order, and takes the first it can match:</p><table tabindex="0"><thead><tr><th>Your system says</th><th>The app speaks</th></tr></thead><tbody><tr><td><code>pt-BR</code>, or <code>pt</code> with no region</td><td>Português (Brasil)</td></tr><tr><td><code>pt-PT</code>, <code>pt-AO</code>, <code>pt-MZ</code> or Portuguese of any other region</td><td>Português (Portugal)</td></tr><tr><td><code>en-GB</code>, <code>en-IE</code>, <code>en-AU</code>, <code>en-NZ</code>, <code>en-IN</code>, <code>en-ZA</code>, <code>en-SG</code>, <code>en-HK</code>, <code>en-MT</code></td><td>English (United Kingdom)</td></tr><tr><td><code>en-CA</code></td><td>English (Canada)</td></tr><tr><td><code>en-US</code>, <code>en</code> with no region, or English of any other region</td><td>English (United States)</td></tr><tr><td>A language the app does not carry yet</td><td>The next language in your system&#39;s list, else English (United States)</td></tr></tbody></table><p>So a system set to French, then Portuguese (Brazil), gets the app in Brazilian Portuguese.</p><p>On Windows the installer and uninstaller speak English (United States), Português (Brasil) or Português (Portugal).</p><h2 id="the-story-s-language" tabindex="-1">The story&#39;s language <a class="header-anchor" href="#the-story-s-language" aria-label="Permalink to &quot;The story&#39;s language&quot;">​</a></h2><p>Each story has its own language. Until you set one, Leathercase tells it from the prose, by which language&#39;s commonest little words the text uses most (&quot;the&quot;, &quot;and&quot;, &quot;of&quot;; &quot;de&quot;, &quot;que&quot;, &quot;não&quot;; &quot;el&quot;, &quot;y&quot;, &quot;una&quot;). It can tell English, Portuguese, Spanish, French, German and Italian apart, and needs a few sentences to be sure; until then it reads the story as English. Told from the prose, it is only a language, never a region: Brazilian and European Portuguese share their little words.</p><p><img src="'+r+'" alt="Story settings at Prose, with the Language row showing Told from the prose: English and its hint" width="845" height="325" loading="lazy"></p><p>To set it:</p><ol><li>Open the story, then <strong>Story settings</strong> from the story&#39;s menu in the breadcrumb or the sidebar, or from the <strong>Story</strong> menu.</li><li>Choose <strong>Prose</strong> in the list on the left.</li><li>In <strong>Language</strong>, the first choice says what the prose told Leathercase: <strong>Told from the prose: English</strong>, or <strong>Told from the prose (English until there is enough)</strong>. Pick one of the five languages above to set it yourself. The hint beside the row says <strong>The book&#39;s words and the templates follow the story&#39;s language, not the app&#39;s.</strong></li></ol><p>Set it when the guess is wrong, or when you want the book&#39;s words in a regional spelling: a story set to Português (Portugal) gets European Portuguese chapter numbers.</p><h3 id="what-follows-the-story-s-language" tabindex="-1">What follows the story&#39;s language <a class="header-anchor" href="#what-follows-the-story-s-language" aria-label="Permalink to &quot;What follows the story&#39;s language&quot;">​</a></h3><table tabindex="0"><thead><tr><th>What</th><th>Example in a Portuguese story</th></tr></thead><tbody><tr><td>The beat board&#39;s templates and beats</td><td><strong>Três atos</strong>, with the act <strong>Ato I</strong> holding Abertura, Incidente incitante, Primeira virada</td></tr><tr><td>The acts and scenes a grid template writes into <code>PlotGrid.md</code></td><td><code>### Incidente incitante</code></td></tr><tr><td>The columns a template writes into <code>StoryThreads.md</code></td><td><code>## Theme: Tema principal</code></td></tr><tr><td>The book&#39;s words in an export</td><td>&quot;Capítulo Um&quot;, &quot;Sumário&quot;, &quot;cerca de 1.000 palavras&quot;</td></tr><tr><td>The head of the sentence log, and the readable copy of an agent&#39;s proposal kept in <code>suite/assistant/changesets/</code></td><td>in Portuguese</td></tr><tr><td>How the prose is read</td><td>Portuguese pronouns, articles and honorifics first</td></tr></tbody></table><p>The threads note keeps its grammar in every language: the <code>Arc:</code>, <code>Theme:</code> and <code>Subplot:</code> prefixes, the stop words <code>plant:</code>, <code>payoff:</code>, <code>reversal:</code>, and the <code>beat:</code> comment stay as they are, so a threads file reads the same way whatever language its story is in.</p><p>Chapter numbers are spelled out in English and Portuguese (&quot;Chapter Twelve&quot;, &quot;Capítulo Doze&quot;). For a story in Spanish, French, German or Italian the book&#39;s words come from English until the app carries those languages, and chapter numbers are written as digits.</p><h3 id="reading-a-story-that-mixes-languages" tabindex="-1">Reading a story that mixes languages <a class="header-anchor" href="#reading-a-story-that-mixes-languages" aria-label="Permalink to &quot;Reading a story that mixes languages&quot;">​</a></h3><p>The story&#39;s language goes first, but Leathercase reads every language it knows in every story. A Portuguese line of dialogue in an English novel is read as Portuguese: &quot;Inés encontrou a Nora no cais. Ela sorriu.&quot; finds Nora by &quot;Ela&quot;. Titles at the head of a name are known in all six languages, so &quot;Father Amaro&quot;, &quot;Dona Inés&quot;, &quot;Madame Roca&quot; and &quot;Herr Kell&quot; each find their character and tell their pronoun.</p><p>The style checks (adverbs, clichés, filter verbs, passive voice and the others) are built on English word lists, so they find little in prose written in another language.</p><h2 id="folder-names-in-every-language" tabindex="-1">Folder names in every language <a class="header-anchor" href="#folder-names-in-every-language" aria-label="Permalink to &quot;Folder names in every language&quot;">​</a></h2><p>A note is a character, place, item, faction or event when it sits in a folder named for its kind, and Leathercase reads those names in six languages, singular or plural, in any case. When a note&#39;s front matter says <code>type:</code>, the type wins over the folder.</p><table tabindex="0"><thead><tr><th>Kind</th><th>English</th><th>Português</th><th>Español</th><th>Français</th><th>Deutsch</th><th>Italiano</th></tr></thead><tbody><tr><td>Character</td><td>Characters, Character, People, Cast, Dramatis personae, NPC, NPCs</td><td>Personagens, Personagem, Pessoas, Elenco</td><td>Personajes, Personaje, Personas, Reparto</td><td>Personnages, Personnage, Personnes, Distribution</td><td>Figuren, Figur, Personen, Charaktere, Besetzung</td><td>Personaggi, Personaggio, Persone, Cast</td></tr><tr><td>Place</td><td>Places, Place, Locations, Location, Settings, Setting, World, Worldbuilding, Geography, Maps, Map</td><td>Lugares, Lugar, Locais, Cenários, Mundo, Geografia, Mapas</td><td>Lugares, Lugar, Ubicaciones, Escenarios, Mundo, Geografía, Mapas</td><td>Lieux, Lieu, Endroits, Décors, Monde, Géographie, Cartes</td><td>Orte, Ort, Schauplätze, Welt, Geographie, Geografie, Karten</td><td>Luoghi, Luogo, Ambientazioni, Mondo, Geografia, Mappe</td></tr><tr><td>Item</td><td>Items, Item, Objects, Object, Artifacts, Artifact, Artefacts, Artefact</td><td>Objetos, Objeto, Objectos, Itens, Artefatos, Artefactos</td><td>Objetos, Objeto, Artefactos</td><td>Objets, Objet, Artefacts</td><td>Gegenstände, Gegenstand, Objekte, Artefakte</td><td>Oggetti, Oggetto, Artefatti</td></tr><tr><td>Faction</td><td>Factions, Faction, Organisations, Organizations, Organisation, Organization, Houses, Groups</td><td>Facções, Facção, Organizações, Grupos</td><td>Facciones, Facción, Organizaciones, Grupos</td><td>Organisations, Groupes</td><td>Fraktionen, Fraktion, Organisationen, Gruppen</td><td>Fazioni, Fazione, Organizzazioni, Gruppi</td></tr><tr><td>Event</td><td>Events, Event, Timeline, History</td><td>Eventos, Evento, Cronologia</td><td>Eventos, Evento, Cronología</td><td>Événements, Évènements, Événement, Chronologie</td><td>Ereignisse, Ereignis, Zeitleiste, Chronik</td><td>Eventi, Evento, Cronologia</td></tr></tbody></table><p>Folders that hold notes about the story rather than the story itself are read in the same languages:</p><table tabindex="0"><thead><tr><th>Role</th><th>Folder names</th></tr></thead><tbody><tr><td>Prose</td><td>Manuscript, Chapters, Scenes, Draft, Drafts; Manuscrito, Capítulos, Cenas, Rascunho, Rascunhos; Escenas, Borrador, Borradores; Manuscrit, Chapitres, Scènes; Manuskript, Kapitel; Capitoli, Bozza, Bozze</td></tr><tr><td>Plan</td><td>Outline, Outlines, Planning, Plans, Synopsis; Esboço, Esboços, Planejamento, Planeamento, Sinopse, Escaleta; Planificación; Synopse, Planung; Scaletta</td></tr><tr><td>Record</td><td>Style sheet, Continuity; Continuidade; Continuidad</td></tr><tr><td>Work notes</td><td>Journal, Feedback, Revisions, Revision notes, Critiques; Diário, Revisões, Revisão, Notas de trabalho; Diario, Revisiones; Überarbeitung</td></tr><tr><td>Research</td><td>Research, Sources, Resources, References, Clippings; Pesquisa, Pesquisas, Fontes, Referências; Investigación, Fuentes; Recherche, Recherches; Quellen, Recherchen; Ricerca, Fonti</td></tr><tr><td>Scraps</td><td>Cut, Cuts, Scraps, Archive, Extras, Deleted scenes, Outtakes, Trash; Cortes, Cenas cortadas, Arquivo, Lixo, Lixeira, Descartes; Archivo, Escenas eliminadas; Archives; Archiv; Archivio</td></tr></tbody></table><p>A word two roles could claim, such as &quot;Notes&quot; or &quot;Story&quot;, is left out on purpose: Leathercase asks what such a folder holds instead of guessing. The <code>type:</code> words a note can carry are listed in <a href="/guide/reference/front-matter">Front matter</a>; they are read in the same six languages.</p><p>A new story Leathercase starts for you gets its cast and world folders (<code>Characters/</code>, <code>Places/</code>, <code>Items/</code>, <code>Factions/</code>, <code>Events/</code>) named in the story&#39;s language when one is set as it starts, otherwise in the app&#39;s: <code>Personagens/</code>, <code>Lugares/</code>, <code>Objetos/</code>, <code>Facções/</code>, <code>Eventos/</code> in Portuguese.</p><h2 id="reporting-a-wrong-word" tabindex="-1">Reporting a wrong word <a class="header-anchor" href="#reporting-a-wrong-word" aria-label="Permalink to &quot;Reporting a wrong word&quot;">​</a></h2><p>The app&#39;s translations are written from the English source with a shared glossary, so Leathercase names things the same way on every screen. If a label reads wrong in your language, too literal, the wrong register, a Brazilian word in the Portuguese of Portugal, say which screen and which words. Each fix is one line in one file, made for the next release. Spanish, French, German, Japanese, Korean and Chinese are planned; the app does not carry them yet.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/story-settings">Story settings</a></li><li><a href="/guide/reference/front-matter">Front matter</a></li><li><a href="/guide/guide/export">Export</a></li><li><a href="/guide/reference/settings">Settings</a></li></ul>',46)])])}const f=t(i,[["render",d]]);export{m as __pageData,f as default};
